package com.theemeraldpig.mote;

import android.content.Context;
import android.util.AttributeSet;

import com.theemeraldpig.mote.mobile.EbitenView;

// The game view generated by ebitenmobile, with error reporting kept as the default.
public class MoteView extends EbitenView {
    public MoteView(Context context) { super(context); }
    public MoteView(Context context, AttributeSet attrs) { super(context, attrs); }

    @Override
    protected void onErrorOnGameUpdate(Exception e) { super.onErrorOnGameUpdate(e); }
}
